metrics.workdir_dsl:
workspace "Energy Manager" "Home energy management platform" {

    !identifiers hierarchical

    model {

        homeowner = person "Homeowner" "Manages their household's energy use and costs"

        energyManager = softwareSystem "Energy Manager" "Home energy management platform owned and operated by our company" {

            dashboard = container "Dashboard Web App" "Where homeowners see consumption and costs; embeds the shared rates library that computes energy prices from tariff and time of day" "Web app"

            scheduler = container "Scheduling Service" "Plans charging and heating; embeds the shared rates library that computes energy prices from tariff and time of day" "Service"

            database = container "Database" "Stores meter readings and schedules" "Database" "Database"
        }

        smartMeterProvider = softwareSystem "Smart Meter Provider" "Provides live meter readings; operated by a different organization" "External"

        homeowner -> energyManager.dashboard "views consumption and costs" "HTTPS"
        energyManager.scheduler -> smartMeterProvider "fetches live meter readings" "HTTPS"
        energyManager.dashboard -> energyManager.database "reads meter readings from" "SQL"
        energyManager.scheduler -> energyManager.database "stores meter readings and schedules in" "SQL"
    }

    views {

        systemContext energyManager "SystemContext" {
            include *
            autoLayout
            title "System Context for Energy Manager"
        }

        container energyManager "Containers" {
            include *
            autoLayout
            title "Containers for Energy Manager"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
        }
    }
}
